W={
'ksm-6.01':["Mạng ngang hàng (như mạng gia đình) không cần server; server không bắt buộc.","Server có thể là máy ảo hoặc nhiều máy; không nhất thiết là một máy vật lí cấu hình cao riêng.","Server là hệ thống gồm phần cứng và phần mềm cung cấp dịch vụ cho máy khách.","Server gồm cả phần cứng lẫn phần mềm, không chỉ là phần mềm."],
'ksm-6.02':["Quản trị CSDL là máy chủ cơ sở dữ liệu.","Thẩm định quyền đăng nhập là máy chủ xác thực.","DNS cho biết địa chỉ IP ứng với tên miền để người dùng khỏi nhớ số.","Lưu trữ tệp dùng chung là máy chủ tệp."],
'ksm-6.03':["Nối Internet cần router; switch không thay router.","Chuyển điện–ánh sáng là bộ chuyển đổi quang điện.","Khoảng cách cáp xoắn vẫn khoảng 100 m, không phụ thuộc hub hay switch.","Switch chỉ nối tạm hai cổng đang truyền nên chia nhỏ miền xung đột, hiệu quả hơn hub."],
'ksm-6.04':["Router có cổng WAN nối ra ngoài mạng cục bộ; đây là dấu hiệu nhận biết.","Switch cũng có đèn ở mỗi cổng.","Switch cũng có nhiều cổng RJ45.","Switch cũng nối được nhiều máy bằng cáp xoắn."],
'ksm-6.05':["Giảm tốc độ không kéo dài được khoảng cách của cáp xoắn.","Hub chỉ phát lại ra mọi cổng, không phải thiết bị khuếch đại kéo dài.","Repeater nhận tín hiệu yếu, chỉnh lại rồi phát lại để kéo dài đường truyền.","Máy chủ DNS không liên quan truyền tín hiệu."],
'ksm-6.06':["Đúng: cáp quang ít suy hao nên truyền xa hơn.","Đúng: khó bị lấy trộm tín hiệu hơn cáp đồng.","SAI: máy tính dùng tín hiệu điện nên cần bộ chuyển đổi quang–điện.","Đúng: cáp quang không bị nhiễu điện từ."],
'ksm-6.07':["Mạng vệ tinh dùng cho phạm vi rất rộng.","5G là mạng diện rộng, quá mức cần cho 2 m.","Cáp quang không phải công nghệ không dây.","Bluetooth: phạm vi khoảng 10 m, nối thiết bị cá nhân với nhau."],
'ksm-6.08':["802.11n dùng 2,4/5 GHz, tối đa 450 Mb/s.","802.11g dùng 2,4 GHz, 54 Mb/s.","802.11b dùng 2,4 GHz, 11 Mb/s.","802.11ad dùng dải 60 GHz, tối đa 4,6 Gb/s."],
'ksm-6.09':["Thứ tự 4G → 3G → 5G không tăng dần.","5G không đứng giữa 3G và 4G.","3G 40 Mb/s < 4G 1,5 Gb/s < 5G 10 Gb/s.","Thứ tự này là giảm dần."],
'ksm-6.10':["Chọn switch và cáp cụ thể thuộc thiết kế vật lí.","Cấu trúc kết nối và mô hình workgroup/domain thuộc thiết kế logic.","Vị trí đặt thiết bị thuộc thiết kế vật lí.","Khảo sát số máy thuộc bước khảo sát và phân tích."],
'ksm-6.11':["Mạng nhỏ vẫn cần chọn mô hình kiểm soát.","Mạng dạng vòng không phải mô hình kiểm soát.","Domain cần máy chủ, tài khoản tập trung: phức tạp hơn nhu cầu.","Workgroup: không cần máy chủ, mỗi máy tự quản tài khoản; đơn giản và phù hợp."],
'ksm-6.12':["Hình sao (và phân cấp = sao của các sao) dùng ở hầu hết mạng cục bộ.","Dạng tuyến chỉ còn làm đường trục.","Cáp đồng trục dạng tuyến đã lỗi thời cho mạng cục bộ.","Dạng vòng hầu như không dùng nối trực tiếp máy tính."],
'ksm-6.13':["Tối đa 5 là số phân đoạn, không phải repeater.","Quy tắc 5-4-3: tối đa 4 repeater.","2 không phải giới hạn của quy tắc.","3 là số phân đoạn có máy tính."],
'ksm-6.14':["Đúng: quy mô địa lí ảnh hưởng chọn thiết bị và đường truyền.","Đúng: tính mĩ thuật là yếu tố thứ yếu.","SAI: xác định ứng dụng cài đặt không phải bước thiết kế mạng, nhưng ảnh hưởng chọn mô hình.","Đúng: kinh phí chỉ tính được sau khi đã có thiết kế."],
'ksm-6.15':["Đúng mục đích: giới hạn xung đột.","Đúng mục đích: bảo vệ dữ liệu quan trọng.","Không phải mục đích: tăng số máy chủ.","Đúng mục đích: cô lập sự cố."],
'ksm-6.16':["5 switch 32 cổng = 160 cổng, dư rất nhiều.","Switch tổng chỉ cần 5 cổng nên 16 cổng là dư.","Mỗi phòng 20+1+1+1 = 23 → 24 cổng; switch tổng 4+1 = 5 → 8 cổng: ít cổng nhất.","16 cổng ở mỗi phòng không đủ 23 cổng."],
'ksm-6.17':["45 s nhầm: 450 MB ÷ 10 = 45, thiếu nhân 8 bit.","450 MB = 3600 Mb; 3600 ÷ 100 = 36 s.","4,5 s thiếu hệ số 8 và lệch một bậc.","360 s nhân thừa 10."],
'ksm-6.18':["Tổng 40×3 = 120 Mb/s > 100 Mb/s nên cần Gigabit.","Fast Ethernet 100 Mb/s không đủ tổng nhu cầu 120 Mb/s.","10BASE-T 10 Mb/s quá thấp.","Bluetooth khoảng 1 Mb/s quá thấp."],
'ksm-6.19':["Repeater không giúp chia sẻ máy in.","Cần ba điều kiện: máy in được chia sẻ, hai máy cùng mạng nội bộ, máy in có driver.","Chung Internet chưa đủ; cần cùng mạng nội bộ và chia sẻ máy in.","Thiếu: Hà phải chia sẻ máy in."],
'ksm-M1':["Switch nối tạm hai cổng giảm xung đột; hub phát ra mọi cổng.","Router có cổng WAN.","Chọn đường là việc của router, không phải hub/switch.","Repeater chỉ chỉnh tín hiệu, không tăng tốc."],
'ksm-M2':["8 cổng quá ít.","30 + 1 + 1 = 32 → chọn loại 32 cổng.","24 cổng không đủ.","16 cổng không đủ."],
'ksm-M3':["Chọn hệ điều hành mạng là bước cuối, sau thiết kế vật lí.","Không thể trước khi khảo sát.","Không đồng thời với thiết kế logic.","Không nằm giữa khảo sát và thiết kế logic."],
'ksm-M4':["2G chỉ nghe gọi và SMS.","3G tối đa khoảng 40 Mb/s.","4G tối đa khoảng 1,5 Gb/s.","5G đạt khoảng 10 Gb/s, độ trễ thấp, phù hợp IoT."],
'ksm-M5':["Có nhãn (bản chép lời) → học có giám sát.","Mô phỏng không phải học từ dữ liệu có nhãn.","Có nhãn thì không phải không giám sát.","Đây vẫn là học máy."],
'ksm-M6':["Volume là khối lượng.","Veracity là tính xác thực: dữ liệu cần kiểm tra vì có nhiễu hoặc sai số.","Variety là đa dạng.","Velocity là tốc độ."],
'ksm-M8':["Mô phỏng tạo mô hình ảo để thử nghiệm; học máy học từ dữ liệu để dự đoán.","Hai kĩ thuật khác nhau.","Mô phỏng không đòi hỏi dữ liệu có nhãn.","Hai kĩ thuật dùng ở nhiều lĩnh vực."],
'mang-tbmang-23':["Hub phát ra mọi cổng; switch tạo kênh tạm giữa cổng gửi và nhận.","Chọn đường giữa các mạng là router.","Hub và switch đều là thiết bị có dây.","Hub không nhanh hơn; hub gây xung đột."],
'mang-tbmang-24':["Repeater không thay switch.","Mạng nhà ít thiết bị dùng hub rẻ; văn phòng hàng chục máy nên dùng switch ít xung đột.","Hub không luôn nhanh hơn switch.","Mạng nhà không bắt buộc router chuyên dụng."],
'mang-tbmang-25':["Đặt địa chỉ IP không phải Wi-Fi.","Wi-Fi không phải loại cáp.","Modem quang không phải Wi-Fi.","Wi-Fi là bộ tiêu chuẩn truyền dữ liệu bằng sóng vô tuyến, thiết bị phát là AP."],
'mang-tbmang-26':["Phát ra mọi cổng là hub.","Dữ liệu vào cổng LAN rồi ra cổng WAN tới mạng đích.","Chiều đi là LAN → WAN.","Đổi số–quang là việc của modem quang."],
'mang-tbmang-27':["Chọn đường tối ưu là router.","Gán IP là DHCP.","Modem chuyển đổi tín hiệu số ↔ tương tự, giữ nguyên dữ liệu.","Chia miền xung đột là switch."],
'mang-tbmang-28':["Modem GSM dùng SIM, không cần cáp quang.","Modem quang đổi số ↔ quang, không phải sóng điện thoại.","Modem quang đổi số ↔ quang; ADSL dùng đường cáp điện thoại.","ADSL không dùng sóng 5G."],
'mang-giaothuc-29':["Đảo ngược: SMTP gửi, POP3 nhận.","HTTP, FTP không phải giao thức gửi thư.","DNS, IP không phải giao thức gửi thư.","SMTP gửi thư; POP3 hoặc IMAP nhận thư."],
'mang-giaothuc-30':["Chuyển tên miền là DNS; định dạng trang là HTML.","IP, TCP không nén dữ liệu hay diệt virus.","IP đặt địa chỉ và dẫn đường gói tin; TCP truyền tin cậy.","IP và TCP dùng cả mạng có dây và không dây."],
'mang-giaothuc-31':["Chia gói không bảo đảm không mất dữ liệu.","Chia gói để KHÔNG độc chiếm đường truyền.","Nhiều cuộc truyền xen kẽ cùng đường truyền nên tận dụng được nó.","Vẫn cần địa chỉ IP của máy nhận."],
'mang-giaothuc-32':["SMTP gửi thư.","DNS không phải nền tảng của ping.","FTP truyền tệp.","ping dùng ICMP để kiểm tra kết nối tới máy khác."],
'mang-giaothuc-33':["Dùng @, không dùng #.","Địa chỉ thư có dạng <tài khoản>@<tên miền>.","Đảo thứ tự.","URL web không phải địa chỉ thư."],
'mang-chiase-34':["Không cần tắt diệt virus.","Máy A bật chia sẻ, cấp quyền; hai máy cùng mạng cục bộ.","Mạng xã hội không liên quan.","Không phải trả phí."],
'mang-chiase-35':["Chia sẻ trong LAN không cần Internet.","Chế độ Public hạn chế chia sẻ, không dùng cho chia sẻ.","Bật Network discovery, chia sẻ tệp, máy in; mạng Private.","Xoá tài khoản làm mất bảo mật."],
'mang-chiase-36':["Public chia sẻ tệp, không chỉ máy in.","Mặc định không chia sẻ ra Internet.","Có thể chia sẻ khi bật.","Mặc định không chia sẻ; phải bật chia sẻ công cộng."],
'mang-chiase-37':["Tường lửa kiểm soát truy cập vào máy; có thể chặn chia sẻ nên cần điều chỉnh.","Đó là cáp chống nhiễu.","Đó là bộ khuếch đại (repeater).","Đó là DNS."],
'mang-tbmang-38':["Không bị chặn: các tầng vẫn liên lạc.","Không cùng một miền xung đột.","Không liên quan TCP.","Switch thiết lập kênh tạm giữa hai cổng nên xung đột chỉ nằm trong từng đường truyền."],
'mang-tbmang-39':["Cáp quang dùng ánh sáng, không dùng tín hiệu điện.","Cáp xoắn hiệu quả khoảng 100 m; cáp quang truyền xa, ít nhiễu, băng thông lớn.","Cáp xoắn vẫn truyền được nhưng kém hiệu quả trên 100 m.","Cáp quang thường đắt hơn."],
'cs12-mang-mang-ip-1':["/26 → khối 64: 77 thuộc khối .64; 62 host.","192.168.10.0 là khối đầu, không chứa .77.","64 host chưa trừ địa chỉ mạng và quảng bá.","192.168.10.76 không phải biên khối 64."],
'cs12-mang-mang-ip-2':["/29 chỉ 6 host, thiếu.","/28 chỉ 14 host, thiếu.","/26 có 62 host, dư nhiều hơn mức cần; số liệu ghi trong phương án sai.","/27 có 30 host ≥ 25 và nhỏ nhất đủ dùng."],
'cs12-mang-mang-ip-3':["Khối 16: .140 thuộc .128–.143, .145 thuộc .144–.159; không cùng.","Cả .130 và .140 thuộc khối .128–.143.",".129 thuộc .128; .144 thuộc .144; khác khối.",".130 và .145 khác khối."],
'cs12-mang-mang-ip-4':["172.16.0.0–172.31.255.255 là dải riêng; 172.20.5.1 thuộc dải.","192.169.x.x nằm ngoài 192.168.0.0/16.","172.32.x.x nằm ngoài dải riêng.","11.0.0.0 là địa chỉ công cộng."],
'cs12-mang-mang-bang-thong-5':["0,5 s nhầm bit và byte.","40 s lệch một bậc.","50 MB = 400 Mb; 400 ÷ 100 = 4 s.","5 s sai do nhầm byte/bit."],
'cs12-mang-giaothuc-7':["Cần DNS trước mới biết IP để kết nối TCP.","DNS → TCP → HTTP → nhận trang.","HTTP không gửi được khi chưa có kết nối TCP.","Phải có kết nối TCP rồi mới gửi HTTP."],
'cs12-mang-tbmang-8':["Switch không phát ra mọi cổng.","Hub không chuyển riêng tới đích.","Hub phát ra mọi cổng; switch chỉ tới máy đích.","Hai thiết bị bị đảo vai."],
'cs12-mang-an-toan-9':["Diệt virus là phần mềm diệt virus.","Tăng băng thông không phải việc của tường lửa.","Mã hoá là TLS/HTTPS.","Tường lửa lọc gói tin ra/vào theo luật (địa chỉ, cổng, giao thức)."],
'bn_b-mang-thietbi-7':["Wi-Fi Direct nối trực tiếp hai thiết bị, không qua router, tốc độ cao hơn Bluetooth.","DNS không truyền tệp.","SMTP gửi thư, không phải truyền tệp trực tiếp.","Cáp nối hub của ISP cần Internet."],
'bn_b-mang-thietbi-8':["Switch chỉ chuyển tiếp trong mạng cục bộ.","Máy in không cung cấp Internet.","Trình duyệt là phần mềm.","ISP cung cấp đường truyền và dịch vụ Internet qua modem/router."],
'bn_b-mang-thietbi-9':["Hotspot biến điện thoại thành điểm phát Wi-Fi, dữ liệu qua mạng di động.","Máy tính không nhận trực tiếp từ vệ tinh.","Hotspot cần điện thoại có kết nối dữ liệu.","Nên đặt mật khẩu để bảo vệ."],
'bn_b-mang-thietbi-10':["Không cần cáp quang riêng.","Bluetooth chỉ tầm ngắn.","Không cần cắm chung ổ điện.","Điều khiển từ xa cần Internet và dịch vụ đám mây."],
'h-net-01':["Đó là mạng nếu mặt nạ /24; với /21 khối là 8 trong octet thứ 3.","/21: mặt nạ 255.255.248.0, khối 8 ở octet 3 → 32..39; mạng 172.16.32.0, quảng bá 172.16.39.255.","Quảng bá là địa chỉ CUỐI của khối (.255), không phải .254 (.254 là máy cuối dùng được).","172.16.37.192 là mạng nếu /26; đề cho /21."],
'h-net-02':["Máy thứ ba (25 máy) chỉ cần /27, máy thứ tư (12 máy) cần /28; /26 và /27 lãng phí.","/24 cho 100 máy chiếm hết cả dải 256 địa chỉ, không còn chỗ cho ba mạng kia.","/26 chỉ có 62 host, không đủ cho 100 máy.","100→/25 (126), 50→/26 (62), 25→/27 (30), 12→/28 (14); tổng 240 ≤ 256."],
'h-net-03':["8 mạng 126 máy là kết quả khi chia /22 thành /25.","/22 có 1024 địa chỉ; /26 có 64 → 16 mạng; mỗi mạng 64 − 2 = 62 địa chỉ máy.","64 mạng, 30 máy là khi chia thành /28 hoặc /27 nhỏ hơn; không phải /26.","32 mạng là kết quả khi chia /27; hơn nữa 64 địa chỉ chưa trừ địa chỉ mạng và quảng bá."],
'h-net-04':["80 s là chưa đổi byte sang bit.","2000 MB × 8 = 16 000 Mb; ÷ 160 = 100 s.","12,5 s quên 80% và sai hệ số.","10 s sai bậc."],
'h-net-05':["28 + 2 + 1 = 31; thêm 2 dự phòng = 33 > 32 nên chọn 48 cổng.","32 cổng chỉ còn 1 cổng dự phòng.","16 cổng không đủ.","24 cổng không đủ."],
}
